package com.sijan.bookandreadingtracker.data.local

import androidx.room.Database
import androidx.room.RoomDatabase

@Database(
    entities = [BookEntity::class],
    version = 1,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {
    abstract fun bookDao(): BookDao

    companion object {
        const val DATABASE_NAME = "book_tracker_db"
    }
}

package com.sijan.bookandreadingtracker.data.local

import androidx.room.*
import kotlinx.coroutines.flow.Flow

@Dao
interface BookDao {

    @Query("SELECT * FROM books")
    fun getAllBooks(): Flow<List<BookEntity>>

    @Query("SELECT * FROM books WHERE isInLibrary = 1")
    fun getLibraryBooks(): Flow<List<BookEntity>>

    @Query("SELECT * FROM books WHERE isInLibrary = 1 AND pagesRead > 0 AND pagesRead < pageCount")
    fun getCurrentReads(): Flow<List<BookEntity>>

    @Query("SELECT * FROM books WHERE isInLibrary = 1 AND pagesRead >= pageCount AND pageCount > 0")
    fun getFinishedBooks(): Flow<List<BookEntity>>

    @Query("SELECT * FROM books WHERE id = :id")
    suspend fun getBookById(id: Long): BookEntity?

    @Query("SELECT * FROM books WHERE id = :id")
    fun observeBookById(id: Long): Flow<BookEntity?>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertBook(book: BookEntity): Long

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertBooks(books: List<BookEntity>)

    @Update
    suspend fun updateBook(book: BookEntity)

    @Delete
    suspend fun deleteBook(book: BookEntity)

    @Query("DELETE FROM books WHERE id = :id")
    suspend fun deleteBookById(id: Long)

    @Query("UPDATE books SET pagesRead = :pagesRead WHERE id = :bookId")
    suspend fun updateReadingProgress(bookId: Long, pagesRead: Int)

    @Query("UPDATE books SET personalNote = :note WHERE id = :bookId")
    suspend fun updatePersonalNote(bookId: Long, note: String)

    @Query("UPDATE books SET isInLibrary = :isInLibrary WHERE id = :bookId")
    suspend fun updateLibraryStatus(bookId: Long, isInLibrary: Boolean)

    @Query("SELECT COUNT(*) FROM books WHERE isInLibrary = 1 AND pagesRead >= pageCount AND pageCount > 0")
    fun getFinishedBooksCount(): Flow<Int>

    @Query("SELECT COALESCE(SUM(pagesRead), 0) FROM books WHERE isInLibrary = 1")
    fun getTotalPagesRead(): Flow<Int>
}

package com.sijan.bookandreadingtracker.data.local
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "books") data class BookEntity( @PrimaryKey(autoGenerate = true) val id: Long = 0, val title: String, val author: String, val description: String, val coverUrl: String, val publishedDate: String, val rating: Float, val pageCount: Int, val pdfUrl: String = "", val isInLibrary: Boolean = false, val pagesRead: Int = 0, val personalNote: String = "" ) { val progressPercent: Float get() = if (pageCount > 0) { (pagesRead.toFloat() / pageCount.toFloat()) * 100f } else 0f
val isCurrentlyReading: Boolean get() = isInLibrary && pagesRead > 0 && pagesRead < pageCount
val isFinished: Boolean get() = isInLibrary && pagesRead >= pageCount && pageCount > 0 }

package com.sijan.bookandreadingtracker.data.remote

import com.sijan.bookandreadingtracker.data.remote.dto.GoogleBooksResponse
import retrofit2.http.GET
import retrofit2.http.Query

interface GoogleBooksApiService {

    @GET("volumes")
    suspend fun searchBooks(
        @Query("q") query: String,
        @Query("maxResults") maxResults: Int = 20,
        @Query("startIndex") startIndex: Int = 0
    ): GoogleBooksResponse

    @GET("volumes")
    suspend fun getRecommendedBooks(
        @Query("q") category: String = "fiction",
        @Query("orderBy") orderBy: String = "relevance",
        @Query("maxResults") maxResults: Int = 20
    ): GoogleBooksResponse

    companion object {
        const val BASE_URL = "https://www.googleapis.com/books/v1/"
    }
}

package com.sijan.bookandreadingtracker.data.remote.dto

import com.google.gson.annotations.SerializedName

data class GoogleBooksResponse(
    @SerializedName("items")
    val items: List<BookItemDto>? = null,
    @SerializedName("totalItems")
    val totalItems: Int = 0
)

data class BookItemDto(
    @SerializedName("id")
    val id: String,
    @SerializedName("volumeInfo")
    val volumeInfo: VolumeInfoDto
)

data class VolumeInfoDto(
    @SerializedName("title")
    val title: String?,
    @SerializedName("authors")
    val authors: List<String>?,
    @SerializedName("description")
    val description: String?,
    @SerializedName("imageLinks")
    val imageLinks: ImageLinksDto?,
    @SerializedName("publishedDate")
    val publishedDate: String?,
    @SerializedName("averageRating")
    val averageRating: Float?,
    @SerializedName("pageCount")
    val pageCount: Int?,
    @SerializedName("previewLink")
    val previewLink: String?
)

data class ImageLinksDto(
    @SerializedName("thumbnail")
    val thumbnail: String?,
    @SerializedName("smallThumbnail")
    val smallThumbnail: String?
)

package com.sijan.bookandreadingtracker.data.repository

import com.sijan.bookandreadingtracker.data.local.BookDao
import com.sijan.bookandreadingtracker.data.local.BookEntity
import com.sijan.bookandreadingtracker.data.remote.GoogleBooksApiService
import com.sijan.bookandreadingtracker.data.remote.dto.BookItemDto
import com.sijan.bookandreadingtracker.domain.repository.BookRepository
import kotlinx.coroutines.flow.Flow
import javax.inject.Inject

class BookRepositoryImpl @Inject constructor(
    private val bookDao: BookDao,
    private val apiService: GoogleBooksApiService
) : BookRepository {

    override fun getAllBooks(): Flow<List<BookEntity>> {
        return bookDao.getAllBooks()
    }

    override fun getLibraryBooks(): Flow<List<BookEntity>> {
        return bookDao.getLibraryBooks()
    }

    override fun getCurrentReads(): Flow<List<BookEntity>> {
        return bookDao.getCurrentReads()
    }

    override fun getFinishedBooks(): Flow<List<BookEntity>> {
        return bookDao.getFinishedBooks()
    }

    override suspend fun getBookById(id: Long): BookEntity? {
        return bookDao.getBookById(id)
    }

    override fun observeBookById(id: Long): Flow<BookEntity?> {
        return bookDao.observeBookById(id)
    }

    override suspend fun insertBook(book: BookEntity): Long {
        return bookDao.insertBook(book)
    }

    override suspend fun updateBook(book: BookEntity) {
        bookDao.updateBook(book)
    }

    override suspend fun deleteBook(book: BookEntity) {
        bookDao.deleteBook(book)
    }

    override suspend fun deleteBookById(id: Long) {
        bookDao.deleteBookById(id)
    }

    override suspend fun updateReadingProgress(bookId: Long, pagesRead: Int) {
        bookDao.updateReadingProgress(bookId, pagesRead)
    }

    override suspend fun updatePersonalNote(bookId: Long, note: String) {
        bookDao.updatePersonalNote(bookId, note)
    }

    override suspend fun addToLibrary(bookId: Long) {
        bookDao.updateLibraryStatus(bookId, true)
    }

    override suspend fun removeFromLibrary(bookId: Long) {
        bookDao.updateLibraryStatus(bookId, false)
    }

    override fun getFinishedBooksCount(): Flow<Int> {
        return bookDao.getFinishedBooksCount()
    }

    override fun getTotalPagesRead(): Flow<Int> {
        return bookDao.getTotalPagesRead()
    }

    override suspend fun searchRemoteBooks(query: String): Result<List<BookEntity>> {
        return try {
            val response = apiService.searchBooks(query)
            val books = response.items?.map { it.toBookEntity() } ?: emptyList()
            Result.success(books)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun getRecommendedBooks(): Result<List<BookEntity>> {
        return try {
            val response = apiService.getRecommendedBooks()
            val books = response.items?.map { it.toBookEntity() } ?: emptyList()
            Result.success(books)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    private fun BookItemDto.toBookEntity(): BookEntity {
        return BookEntity(
            id = 0, // Auto-generated by Room when inserted
            title = volumeInfo.title ?: "Unknown Title",
            author = volumeInfo.authors?.joinToString(", ") ?: "Unknown Author",
            description = volumeInfo.description ?: "No description available",
            coverUrl = volumeInfo.imageLinks?.thumbnail?.replace("http://", "https://") ?: "",
            publishedDate = volumeInfo.publishedDate ?: "",
            rating = volumeInfo.averageRating ?: 0f,
            pageCount = volumeInfo.pageCount ?: 0,
            pdfUrl = volumeInfo.previewLink ?: "",
            isInLibrary = false,
            pagesRead = 0,
            personalNote = ""
        )
    }
}

package com.sijan.bookandreadingtracker.di

import android.content.Context
import androidx.room.Room
import com.sijan.bookandreadingtracker.data.local.AppDatabase
import com.sijan.bookandreadingtracker.data.local.BookDao
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.android.qualifiers.ApplicationContext
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object DatabaseModule {

    @Provides
    @Singleton
    fun provideAppDatabase(@ApplicationContext context: Context): AppDatabase {
        return Room.databaseBuilder(
            context,
            AppDatabase::class.java,
            AppDatabase.DATABASE_NAME
        )
            .fallbackToDestructiveMigration()
            .build()
    }

    @Provides
    @Singleton
    fun provideBookDao(database: AppDatabase): BookDao {
        return database.bookDao()
    }
}

package com.sijan.bookandreadingtracker.di

import com.sijan.bookandreadingtracker.data.remote.GoogleBooksApiService
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.util.concurrent.TimeUnit
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {

    @Provides
    @Singleton
    fun provideHttpLoggingInterceptor(): HttpLoggingInterceptor {
        return HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }
    }

    @Provides
    @Singleton
    fun provideOkHttpClient(loggingInterceptor: HttpLoggingInterceptor): OkHttpClient {
        return OkHttpClient.Builder()
            .addInterceptor(loggingInterceptor)
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build()
    }

    @Provides
    @Singleton
    fun provideRetrofit(okHttpClient: OkHttpClient): Retrofit {
        return Retrofit.Builder()
            .baseUrl(GoogleBooksApiService.BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
    }

    @Provides
    @Singleton
    fun provideGoogleBooksApiService(retrofit: Retrofit): GoogleBooksApiService {
        return retrofit.create(GoogleBooksApiService::class.java)
    }
}

